/**
 * Native module loader for ACRYL microVMs Node.js SDK.
 *
 * This module centralizes native binding loading to avoid duplication
 * across simplebox.ts, interactivebox.ts, and index.ts.
 *
 * Uses the napi-generated loader (acrylmicrovm.js) which handles platform
 * detection automatically - tries local file first, then npm package.
 */

import type {
  ApiKeyCredentialConstructor,
  JsAcrylMicrovmConstructor,
  NativeAcrylMicrovmRestOptionsConstructor,
  NativeModule,
} from "./native-contracts.js";

// @ts-expect-error - Generated by napi build --js
import * as native from "../native/acrylmicrovm.js";

/**
 * Get the native ACRYL microVMs module.
 *
 * The module is loaded via the napi-generated loader which handles
 * platform-specific binary selection automatically.
 */
export function getNativeModule(): NativeModule {
  return native as NativeModule;
}

/**
 * Get the JsAcrylMicrovm runtime class from the native module.
 */
export function getJsAcrylMicrovm(): JsAcrylMicrovmConstructor {
  return getNativeModule().JsAcrylMicrovm;
}

/**
 * Get the native ApiKeyCredential class from the native module.
 */
export function getApiKeyCredential(): ApiKeyCredentialConstructor {
  return getNativeModule().ApiKeyCredential;
}

/**
 * Get the native AcrylMicrovmRestOptions class from the native module.
 *
 * Internal — the public `AcrylMicrovmRestOptions` is the pure-TS class in
 * ./options; this is the binding twin consumed by `JsAcrylMicrovm.rest`.
 */
export function getNativeAcrylMicrovmRestOptions(): NativeAcrylMicrovmRestOptionsConstructor {
  return getNativeModule().JsAcrylMicrovmRestOptions;
}
